// [S2] Camera device feature for synthetic lab report upload.
import 'dart:io';
import 'package:file_picker/file_picker.dart';
import 'package:family_veda/providers/active_member_provider.dart';
import 'package:family_veda/providers/records_provider.dart';
import 'package:family_veda/providers/records_roster_provider.dart';
import 'package:family_veda/services/api/mobile_api.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:image_picker/image_picker.dart';

class LabUploadScreen extends ConsumerStatefulWidget {
  const LabUploadScreen({super.key});

  @override
  ConsumerState<LabUploadScreen> createState() => _LabUploadScreenState();
}

class _LabUploadScreenState extends ConsumerState<LabUploadScreen> {
  final _picker = ImagePicker();
  ({String name, String path})? _file;
  bool _uploading = false;
  bool _shared = false;
  String? _message;

  Future<void> _pick(ImageSource source) async {
    final memberId = ref.read(activeMemberProvider);
    try {
      final file = await _picker.pickImage(source: source, imageQuality: 90);
      if (!mounted || ref.read(activeMemberProvider) != memberId) return;
      if (file == null) {
        setState(
          () => _message =
              'No image selected. Camera and photos permission is required for capture.',
        );
        return;
      }
      setState(() {
        _file = (name: file.name, path: file.path);
        _message = null;
      });
    } catch (_) {
      if (mounted) {
        setState(
          () => _message =
              'Camera or photos access was denied. Enable it in Settings, or choose an image from the gallery.',
        );
      }
    }
  }

  Future<void> _pickPdf() async {
    final memberId = ref.read(activeMemberProvider);
    try {
      final file = await FilePicker.pickFile(
        type: FileType.custom,
        allowedExtensions: const ['pdf'],
      );
      if (!mounted || ref.read(activeMemberProvider) != memberId) return;
      final path = file?.path;
      if (file == null || path == null) {
        setState(() => _message = 'No PDF selected.');
        return;
      }
      // A null length means the size could not be read, so the cap cannot be verified.
      final size = await file.length();
      if (!mounted || ref.read(activeMemberProvider) != memberId) return;
      if (!file.name.toLowerCase().endsWith('.pdf') ||
          size == null ||
          size > 10485760) {
        setState(() => _message = 'Choose a PDF report up to 10 MB.');
        return;
      }
      setState(() {
        _file = (name: file.name, path: path);
        _message = null;
      });
    } catch (_) {
      if (mounted) {
        setState(
          () => _message =
              'The PDF could not be opened. Choose another file or use manual entry.',
        );
      }
    }
  }

  Future<void> _upload() async {
    final memberId = ref.read(activeMemberProvider);
    if (_file == null || memberId == null) return;
    final file = _file!;
    final shared = _shared;
    setState(() {
      _uploading = true;
      _message = null;
    });
    try {
      if (await File(file.path).length() > 10485760) {
        if (mounted && ref.read(activeMemberProvider) == memberId) {
          setState(() => _message = 'Choose a report up to 10 MB.');
        }
        return;
      }
      if (!mounted || ref.read(activeMemberProvider) != memberId) return;
      await ref
          .read(mobileApiProvider)
          .uploadLabReport(
            memberId: memberId,
            path: file.path,
            sharedWithFamilyHead: shared,
          );
      ref.invalidate(memberLabReportsProvider);
      ref.invalidate(labReportsByMemberProvider);
      if (mounted && ref.read(activeMemberProvider) == memberId) {
        setState(() {
          _file = null;
          _message =
              'Report uploaded. It is being read in the background; you can upload more or leave. Check the values in Health records when ready.';
        });
      }
    } on SavedReportUploadException catch (error) {
      ref.invalidate(memberLabReportsProvider);
      ref.invalidate(labReportsByMemberProvider);
      if (mounted && ref.read(activeMemberProvider) == memberId) {
        setState(() {
          _file = null;
          _message = error.message;
        });
      }
    } catch (_) {
      if (mounted && ref.read(activeMemberProvider) == memberId) {
        setState(
          () => _message =
              'Upload could not be confirmed. Check Health records before retrying, or use manual entry.',
        );
      }
    } finally {
      if (mounted) setState(() => _uploading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    ref.listen<String?>(activeMemberProvider, (previous, next) {
      if (previous != next) {
        setState(() {
          _file = null;
          _shared = false;
          _message = null;
        });
      }
    });
    final canShare =
        ref.watch(myMemberIdProvider).valueOrNull != null &&
        ref.watch(myMemberIdProvider).valueOrNull ==
            ref.watch(activeMemberProvider);
    return Scaffold(
      appBar: AppBar(title: const Text('Upload lab report')),
      body: SafeArea(
        child: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            Card(
              child: Padding(
                padding: const EdgeInsets.all(20),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Icon(
                      Icons.upload_file_outlined,
                      size: 36,
                      color: Theme.of(context).colorScheme.primary,
                    ),
                    const SizedBox(height: 12),
                    Text(
                      'Keep your reports together',
                      style: Theme.of(context).textTheme.headlineSmall,
                    ),
                    const SizedBox(height: 8),
                    const Text(
                      'Choose a PDF or a clear photo. Use synthetic reports only. OCR is assistive and never authoritative.',
                    ),
                  ],
                ),
              ),
            ),
            const SizedBox(height: 16),
            FilledButton.icon(
              onPressed: _uploading ? null : () => _pick(ImageSource.camera),
              icon: const Icon(Icons.camera_alt_outlined),
              label: const Text('Take photo'),
            ),
            const SizedBox(height: 12),
            OutlinedButton.icon(
              onPressed: _uploading ? null : () => _pick(ImageSource.gallery),
              icon: const Icon(Icons.photo_library_outlined),
              label: const Text('Choose image'),
            ),
            const SizedBox(height: 12),
            OutlinedButton.icon(
              onPressed: _uploading ? null : _pickPdf,
              icon: const Icon(Icons.picture_as_pdf_outlined),
              label: const Text('Choose PDF'),
            ),
            const SizedBox(height: 24),
            Text(
              'Report visibility',
              style: Theme.of(context).textTheme.titleMedium,
            ),
            const SizedBox(height: 8),
            SegmentedButton<bool>(
              segments: const [
                ButtonSegment(
                  value: false,
                  label: Text('Private'),
                  icon: Icon(Icons.lock_outline),
                ),
                ButtonSegment(
                  value: true,
                  label: Text('Shared with Family Head'),
                  icon: Icon(Icons.people_outline),
                ),
              ],
              selected: {_shared},
              onSelectionChanged: _uploading || !canShare
                  ? null
                  : (values) => setState(() => _shared = values.first),
            ),
            const SizedBox(height: 8),
            Text(
              canShare
                  ? 'Private keeps this report hidden from the Family Head. Sharing does not change doctor access or consent.'
                  : 'Only the adult report owner can change Family Head sharing. Guardian access follows existing permissions.',
            ),
            if (_file != null) ...[
              const SizedBox(height: 20),
              Text('Selected: ${_file!.name}'),
              const SizedBox(height: 12),
              FilledButton(
                onPressed: _uploading ? null : _upload,
                child: Text(_uploading ? 'Uploading…' : 'Upload for review'),
              ),
            ],
            if (_message != null) ...[
              const SizedBox(height: 16),
              Text(_message!, semanticsLabel: _message),
            ],
          ],
        ),
      ),
    );
  }
}
